using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "TidalJetAction", menuName = "Data/Battle/Battle Actions/Cellarius/ExtraPurify Action")]
public class TidalJetAction : PurifyMinimunWaveBaseAction
{
	[SerializeField]
	private PurifiedLightningAction purifiedLightningAction;

	[SerializeField]
	private int purifiedLightningTimesAmount;

	public int PurifiedLightningTimesAmount => purifiedLightningTimesAmount;

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		UnitEffects component = target.GetComponent<UnitEffects>();
		if (component.IsEffectActiveGetAmount(waveEffect) >= minimunWaveAmount)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 2, delegate
			{
				purifiedLightningAction.SingleTargetCastDefault(target, purifiedLightningTimesAmount + 1, purifyAmount, source);
			});
			if (waveCost > 0)
			{
				component.IsEffectActiveAndDecreaseEffect(waveEffect, waveCost);
			}
		}
		else
		{
			ApplyWave(target);
			purifyAction.CastTargetAmount(target, purifyAmount, source);
			CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		}
	}
}
